package com.synexia.rewrite;

import java.lang.annotation.Annotation;
import java.lang.reflect.Array;
import java.lang.reflect.Constructor;
import java.lang.reflect.Executable;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.lang.reflect.RecordComponent;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;

/**
 * Additional reflection-visible contract evidence for the canonical mastery lab.
 * Does not explicitly initialize observed classes or read arbitrary static field values.
 * Annotation resolution may initialize referenced enum types; this is not a sandbox.
 * Source-retained/type-use annotations, constant values and behavioral equivalence still require
 * source/probe gates. Evidence is scoped to the pinned JDK, not a universal API-equivalence proof.
 */
final class M3MasteryContractSurface {
    private M3MasteryContractSurface() {}

    static void append(List<String> lines, Class<?> type, Runnable checkCanceled) {
        Objects.requireNonNull(lines, "lines");
        Objects.requireNonNull(type, "type");
        append(lines, type, Objects.requireNonNull(checkCanceled, "checkCanceled"), 0);
    }

    private static void append(List<String> lines, Class<?> type, Runnable check, int depth) {
        check.run();
        if (depth > 32) throw new IllegalArgumentException("contract nesting exceeds budget");
        row(lines, "V2:class", type.toGenericString());
        row(lines, "V2:super", type.getName(), typeName(type.getGenericSuperclass()));
        for (Type parent : type.getGenericInterfaces()) {
            row(lines, "V2:interface", type.getName(), parent.getTypeName());
        }
        annotations(lines, "class:" + type.getName(), type.getDeclaredAnnotations());
        row(lines, "V2:sealed", type.getName(), Boolean.toString(type.isSealed()));
        if (type.isSealed()) {
            for (Class<?> permitted : type.getPermittedSubclasses()) {
                row(lines, "V2:permits", type.getName(), permitted.getName());
            }
        }
        row(lines, "V2:record", type.getName(), Boolean.toString(type.isRecord()));
        if (type.isRecord()) {
            RecordComponent[] components = type.getRecordComponents();
            for (int i = 0; i < components.length; i++) {
                RecordComponent component = components[i];
                String owner = type.getName() + ":" + i + ":" + component.getName();
                row(lines, "V2:component", owner, component.getGenericType().getTypeName());
                annotations(lines, owner, component.getDeclaredAnnotations());
            }
        }
        for (Constructor<?> constructor : type.getDeclaredConstructors()) {
            check.run();
            if (visible(constructor.getModifiers())) {
                row(lines, "V2:constructor", constructor.toGenericString());
                executable(lines, constructor, check);
            }
        }
        for (Field field : type.getDeclaredFields()) {
            check.run();
            if (visible(field.getModifiers())) {
                row(lines, "V2:field", field.toGenericString());
                annotations(lines, field.toGenericString(), field.getDeclaredAnnotations());
            }
        }
        for (Method method : type.getDeclaredMethods()) {
            check.run();
            if (visible(method.getModifiers())) {
                // Bridges are part of the callable bytecode surface even when source-synthetic.
                row(lines, "V2:method", method.toGenericString(),
                        Boolean.toString(method.isBridge()), Boolean.toString(method.isSynthetic()),
                        Boolean.toString(method.isDefault()));
                executable(lines, method, check);
                row(lines, "V2:annotation-default", method.toGenericString(), value(method.getDefaultValue(), 0));
            }
        }
        for (Class<?> member : type.getDeclaredClasses()) {
            check.run();
            if (visible(member.getModifiers())) append(lines, member, check, depth + 1);
        }
    }

    private static void executable(List<String> lines, Executable member, Runnable check) {
        String owner = member.toGenericString();
        row(lines, "V2:varargs", owner, Boolean.toString(member.isVarArgs()));
        // Explicit rows retain checked/generic throws even where erased signatures are identical.
        for (Type exception : member.getGenericExceptionTypes()) {
            check.run();
            row(lines, "V2:throws", owner, exception.getTypeName());
        }
        annotations(lines, owner, member.getDeclaredAnnotations());
        Annotation[][] parameters = member.getParameterAnnotations();
        for (int i = 0; i < parameters.length; i++) annotations(lines, owner + ":arg" + i, parameters[i]);
    }

    private static void annotations(List<String> lines, String owner, Annotation[] annotations) {
        for (Annotation annotation : annotations) row(lines, "V2:annotation", owner, value(annotation, 0));
    }

    private static String value(Object value, int depth) {
        if (depth > 32) throw new IllegalArgumentException("annotation nesting exceeds budget");
        if (value == null) return "null";
        if (value instanceof Annotation annotation) {
            List<String> members = new ArrayList<>();
            for (Method method : annotation.annotationType().getDeclaredMethods()) {
                try {
                    if (!method.canAccess(annotation) && !method.trySetAccessible()) {
                        throw new IllegalStateException("inaccessible annotation member: " + method);
                    }
                    members.add(frame(method.getName()) + valueFrame(value(method.invoke(annotation), depth + 1)));
                } catch (ReflectiveOperationException failure) {
                    throw new IllegalStateException("annotation observation failed", failure);
                }
            }
            members.sort(String::compareTo);
            return "annotation-v3:" + frame(annotation.annotationType().getName()) + String.join("", members);
        }
        if (value.getClass().isArray()) {
            StringBuilder out = new StringBuilder("array-v3:").append(Array.getLength(value)).append(':');
            for (int i = 0; i < Array.getLength(value); i++) out.append(valueFrame(value(Array.get(value, i), depth + 1)));
            return out.toString();
        }
        if (value instanceof Class<?> type) return "class:" + frame(type.getName());
        if (value instanceof Enum<?> constant) {
            return "enum:" + frame(constant.getDeclaringClass().getName()) + frame(constant.name());
        }
        if (value instanceof String || value instanceof Character || value instanceof Boolean
                || value instanceof Byte || value instanceof Short || value instanceof Integer
                || value instanceof Long || value instanceof Float || value instanceof Double) {
            return value.getClass().getName() + ':' + frame(value.toString());
        }
        throw new IllegalArgumentException("unsupported annotation value: " + value.getClass().getName());
    }

    /** Raw leaves are hex-framed once; an already-ASCII value needs only a length boundary. */
    private static String valueFrame(String encoded) {
        return encoded.length() + ":" + encoded;
    }

    private static String typeName(Type type) {
        return type == null ? "" : type.getTypeName();
    }

    private static boolean visible(int modifiers) {
        return Modifier.isPublic(modifiers) || Modifier.isProtected(modifiers);
    }

    private static void row(List<String> lines, String tag, String... values) {
        lines.add(tag + Arrays.stream(values).map(M3MasteryContractSurface::frame)
                .reduce("", String::concat));
    }

    /** ASCII hex of exact UTF-16 units avoids newline framing and lone-surrogate replacement. */
    private static String frame(String text) {
        StringBuilder out = new StringBuilder().append(text.length()).append(':');
        for (int i = 0; i < text.length(); i++) {
            char unit = text.charAt(i);
            for (int shift = 12; shift >= 0; shift -= 4) out.append(Character.forDigit((unit >>> shift) & 15, 16));
        }
        return out.toString();
    }
}

