import org.openrewrite.text.PlainText;
import org.openrewrite.tree.ParseError;

/**
 * Canonical parser -> LST/SourceFile -> recipe -> printer loop for exactly one source atom.
 *
 * <p>Java, YAML, XML, JSON and properties use their language-specific lossless parser. Any other
 * textual source uses the OpenRewrite plain-text SourceFile lane. The runner reparses between
 * passes so each candidate is independently attributable and print-idempotent before M3 proof.</p>
 */
public final class M3OpenRewriteTranspiler {
    private M3OpenRewriteTranspiler() {}

    /**
     * Compatibility six-leaf mechanical entry point with the current IOP pattern/class fences.
     *
     * <p>The explicit {@link #runIopPatternMechanical(String, String)} and
     * {@link #runFullMechanical(String, String)} entry points retain the complete admitted
     * static-analysis plan.</p>
     */
    public static M3TranspileRun runMechanical(String sourcePath, String source) {
        String normalizedPath = normalizeSourcePath(sourcePath);
        return run(
                normalizedPath,
                source,
                List.of(),
                M3IopPatternMechanicalPasses.mechanicalForPattern(normalizedPath));
    }

    /** Canonical M3Scale Java mutation entry point for explicit IOP pattern code. */
    public static M3TranspileRun runIopPatternMechanical(String sourcePath, String source) {
        return run(sourcePath, source, List.of(), M3IopPatternMechanicalPasses.forFile(sourcePath));
    }

    /** Deterministic IOP source-fence/class-hook authority evidence without applying a mutation. */
    public static M3IopFullScaleMutationAuthority.AuthorityReceipt inspectIopAuthority(
            String sourcePath,
            String source) {
        return inspectIopAuthority(sourcePath, source, List.of());
    }

    /** Deterministic IOP authority evidence with caller-supplied compile classpath. */
    public static M3IopFullScaleMutationAuthority.AuthorityReceipt inspectIopAuthority(
            String sourcePath,
            String source,
            List<Path> classpath) {
        String normalizedPath = normalizeSourcePath(sourcePath);
        requireTextSource(source);
        Parsed parsed = parseLosslessly(
                normalizedPath,
                source,
                classpath(classpath),
                M3SourceKind.JAVA);
        if (!(parsed.source() instanceof J.CompilationUnit unit)) {
            throw new IllegalStateException("Java parser did not return a compilation unit");
        }
        return M3IopFullScaleMutationAuthority.receipt(unit, normalizedPath);
    }

    /** Compatibility alias. IOP path membership alone does not grant mutation authority. */
    public static M3TranspileRun runIopMechanical(String sourcePath, String source) {
        return runIopPatternMechanical(sourcePath, source);
    }

    /** Compatibility full M3 Java entry point; all passes are pattern-class-hooked. */
    public static M3TranspileRun runFullMechanical(String sourcePath, String source) {
        return runIopPatternMechanical(sourcePath, source);
    }

    /**
     * Existing Java-only explicit recipe runner.
     *
     * <p>This method preserves the original Java contract. Use {@link #runSourceCandidate} for
     * YAML/XML/JSON/properties/plain-text SourceFile candidates.</p>
     */
    public static M3TranspileRun run(
            String sourcePath,
            String source,
            List<M3TranspilePass> passes) {
        return run(sourcePath, source, List.of(), passes);
    }

    /** Existing Java-only explicit recipe runner with caller-supplied compile classpath. */
    public static M3TranspileRun run(
            String sourcePath,
            String source,
            List<Path> classpath,
            List<M3TranspilePass> passes) {
        return runInternal(sourcePath, source, classpath, passes, true);
    }

    /** Universal one-source candidate runner. Every mutation is still an OpenRewrite Recipe. */
    public static M3TranspileRun runSourceCandidate(
            String sourcePath,
            String source,
            List<M3TranspilePass> passes) {
        return runSourceCandidate(sourcePath, source, List.of(), passes);
    }

    /**
     * Universal one-source candidate runner with Java classpath support when the source is Java.
     *
     * <p>Unknown textual extensions intentionally fall back to PlainText. NUL-bearing/binary input
     * is rejected from this String-based mutation API.</p>
     */
    public static M3TranspileRun runSourceCandidate(
            String sourcePath,
            String source,
            List<Path> classpath,
            List<M3TranspilePass> passes) {
        return runInternal(sourcePath, source, classpath, passes, false);
    }

    private static M3TranspileRun runInternal(
            String sourcePath,
            String source,
            List<Path> classpath,
            List<M3TranspilePass> passes,
            boolean javaOnly) {
        String normalizedPath = javaOnly
                ? normalizeSourcePath(sourcePath)
                : normalizeSourcePathOrDirectory(sourcePath);
        requireTextSource(source);
        List<Path> checkedClasspath = classpath(classpath);
        List<M3TranspilePass> checkedPasses =
                List.copyOf(Objects.requireNonNull(passes, "passes"));
        requireUniquePassIds(checkedPasses);

        M3SourceKind sourceKind = javaOnly ? M3SourceKind.JAVA : M3SourceKind.classify(normalizedPath);
        String inputHash = sha256(source);
        String current = source;
        ArrayList<M3TranspilePassResult> receipts = new ArrayList<>(checkedPasses.size());

        if (checkedPasses.isEmpty()) {
            parseLosslessly(normalizedPath, current, checkedClasspath, sourceKind);
        }

        for (int index = 0; index < checkedPasses.size(); index++) {
            M3TranspilePass pass = checkedPasses.get(index);
            String beforeHash = sha256(current);
            M3OpenRewriteExecution execution = executeSingleInternal(
                    normalizedPath,
                    current,
                    checkedClasspath,
                    pass,
                    sourceKind);
            current = execution.after();
            String afterHash = sha256(current);
            receipts.add(new M3TranspilePassResult(
                    index + 1,
                    pass.id(),
                    pass.recipe().getName(),
                    normalizedPath,
                    beforeHash,
                    afterHash,
                    !beforeHash.equals(afterHash)));
        }

        return new M3TranspileRun(
                normalizedPath,
                inputHash,
                sha256(current),
                current,
                receipts);
    }

    /** Execute exactly one Java scheduler cycle and return diagnostic recipe/diff evidence. */
    public static M3OpenRewriteExecution executeSingle(
            String sourcePath,
            String source,
            List<Path> classpath,
            M3TranspilePass pass) {
        String normalizedPath = normalizeSourcePath(sourcePath);
        requireTextSource(source);
        return executeSingleInternal(
                normalizedPath,
                source,
                classpath(classpath),
                Objects.requireNonNull(pass, "pass"),
                M3SourceKind.JAVA);
    }

    /** Execute exactly one recipe cycle against any admitted textual SourceFile kind. */
    public static M3OpenRewriteExecution executeSingleSource(
            String sourcePath,
            String source,
            List<Path> classpath,
            M3TranspilePass pass) {
        String normalizedPath = normalizeSourcePathOrDirectory(sourcePath);
        requireTextSource(source);
        return executeSingleInternal(
                normalizedPath,
                source,
                classpath(classpath),
                Objects.requireNonNull(pass, "pass"),
                M3SourceKind.classify(normalizedPath));
    }


    /**
     * One deterministic OpenRewrite scheduler cycle over an exact textual project.
     *
     * <p>The path set is immutable: recipes may rewrite existing sources but may not create,
     * delete, move or rename them. The caller retains compiler, behavior, contract and
     * fixed-point authority.</p>
     */
    public record ProjectExecution(
            Map<String, String> before,
            Map<String, String> after,
            List<M3OpenRewriteExecution> changes) {
        public ProjectExecution {
            before = projectSources(before);
            after = projectSources(after);
            changes = List.copyOf(Objects.requireNonNull(changes, "changes"));
            if (!before.keySet().equals(after.keySet())) {
                throw new IllegalArgumentException("PROJECT_PATH_SET_CHANGED");
            }
            Set<String> changedPaths = new HashSet<>();
            for (M3OpenRewriteExecution change : changes) {
                if (!before.containsKey(change.sourcePath())
                        || !changedPaths.add(change.sourcePath())) {
                    throw new IllegalArgumentException("INVALID_PROJECT_CHANGE_SET");
                }
            }
        }

        /** Source-text changes; raw AST result evidence remains available in changes(). */
        public boolean changed() {
            return !before.equals(after);
        }

        /** Number of paths whose source text changed, independent of raw AST result count. */
        public int changedFiles() {
            return (int) before.entrySet().stream()
                    .filter(entry -> !entry.getValue().equals(after.get(entry.getKey())))
                    .count();
        }
    }

    /** Execute one project cycle with no additional execution-context configuration. */
    public static ProjectExecution executeProjectCycle(
            Map<String, String> sources,
            List<Path> classpath,
            M3TranspilePass pass) {
        return executeProjectCycle(sources, classpath, pass, context -> {});
    }

    /**
     * Execute one project cycle after the trusted host configures the shared execution context.
     *
     * <p>The context hook exists for proof-gated recipes. It runs before parsing and does not
     * receive a mutation surface.</p>
     */
    public static ProjectExecution executeProjectCycle(
            Map<String, String> sources,
            List<Path> classpath,
            M3TranspilePass pass,
            Consumer<InMemoryExecutionContext> contextConfigurer) {
        Map<String, String> input = projectSources(sources);
        List<Path> checkedClasspath = classpath(classpath);
        M3TranspilePass checkedPass = Objects.requireNonNull(pass, "pass");
        Recipe recipe = checkedPass.recipe();
        if (recipe.validateAll().stream().anyMatch(validation -> !validation.isValid())) {
            throw new IllegalArgumentException(
                    "invalid OpenRewrite recipe configuration: " + checkedPass.id());
        }
        boolean hasPython = input.keySet().stream()
                .map(M3SourceKind::classify)
                .anyMatch(kind -> kind == M3SourceKind.PYTHON);
        if (hasPython && !(recipe instanceof M3PythonRecipe)) {
            throw new IllegalArgumentException(
                    "Python source requires an admitted M3PythonRecipe");
        }

        InMemoryExecutionContext context =
                new InMemoryExecutionContext(
                        failure -> {
                            throw new IllegalStateException(
                                    "OpenRewrite project execution failed",
                                    failure);
                        });
        Objects.requireNonNull(contextConfigurer, "contextConfigurer").accept(context);
        List<SourceFile> parsed =
                parseProjectLosslessly(input, checkedClasspath, context);

        List<Result> rawChanges =
                recipe.run(
                                new InMemoryLargeSourceSet(parsed),
                                context,
                                1)
                        .getChangeset()
                        .getAllResults();
        List<Result> orderedChanges = rawChanges.stream()
                .sorted(Comparator.comparing(M3OpenRewriteTranspiler::resultPath))
                .toList();

        TreeMap<String, String> output = new TreeMap<>(input);
        Set<String> changedPaths = new HashSet<>();
        ArrayList<M3OpenRewriteExecution> executions =
                new ArrayList<>(orderedChanges.size());
        for (Result result : orderedChanges) {
            SourceFile before = result.getBefore();
            SourceFile after = result.getAfter();
            if (before == null || after == null) {
                throw new IllegalStateException(
                        "project cycle may not create or delete sources");
            }
            String beforePath =
                    normalizeSourcePathOrDirectory(before.getSourcePath().toString());
            String afterPath =
                    normalizeSourcePathOrDirectory(after.getSourcePath().toString());
            if (!beforePath.equals(afterPath)) {
                throw new IllegalStateException(
                        "project cycle may not move or rename sources");
            }
            String expectedBefore = input.get(beforePath);
            if (expectedBefore == null || !expectedBefore.equals(before.printAll())) {
                throw new IllegalStateException(
                        "project cycle result is not bound to input source: " + beforePath);
            }
            if (!changedPaths.add(beforePath)) {
                throw new IllegalStateException(
                        "project cycle returned duplicate result: " + beforePath);
            }
            M3SourceKind sourceKind = M3SourceKind.classify(beforePath);
            if (sourceKind.structured() && after instanceof PlainText) {
                throw new IllegalStateException(
                        "structured source recipe may not downgrade "
                                + sourceKind
                                + " to plain text");
            }

            String rendered = after.printAll();
            requireTextSource(rendered);
            output.put(beforePath, rendered);
            List<String> descriptors =
                    result.getRecipeDescriptorsThatMadeChanges().stream()
                            .map(descriptor -> descriptor.getName())
                            .toList();
            executions.add(
                    new M3OpenRewriteExecution(
                            beforePath,
                            expectedBefore,
                            rendered,
                            recipe.getClass().getName(),
                            recipe.getDisplayName(),
                            descriptors,
                            result.diff()));
        }

        if (!output.keySet().equals(input.keySet())) {
            throw new IllegalStateException("project cycle changed source path set");
        }
        Map<String, String> immutableOutput = projectSources(output);
        parseProjectLosslessly(
                immutableOutput,
                checkedClasspath,
                new InMemoryExecutionContext(
                        failure -> {
                            throw new IllegalStateException(
                                    "OpenRewrite project reparse failed",
                                    failure);
                        }));
        return new ProjectExecution(input, immutableOutput, executions);
    }

    private static M3OpenRewriteExecution executeSingleInternal(
            String normalizedPath,
            String source,
            List<Path> classpath,
            M3TranspilePass pass,
            M3SourceKind sourceKind) {
        Recipe recipe = pass.recipe();
        if (sourceKind == M3SourceKind.PYTHON
                && !(recipe instanceof M3PythonRecipe)) {
            throw new IllegalArgumentException(
                    "Python source requires an admitted M3PythonRecipe");
        }
        if (recipe.validateAll().stream().anyMatch(validation -> !validation.isValid())) {
            throw new IllegalArgumentException(
                    "invalid OpenRewrite recipe configuration: " + pass.id());
        }

        Parsed parsed = parseLosslessly(normalizedPath, source, classpath, sourceKind);
        List<Result> changes =
                recipe.run(
                                new InMemoryLargeSourceSet(List.of(parsed.source())),
                                parsed.context(),
                                1)
                        .getChangeset()
                        .getAllResults();

        if (changes.isEmpty()) {
            return new M3OpenRewriteExecution(
                    normalizedPath,
                    source,
                    source,
                    recipe.getClass().getName(),
                    recipe.getDisplayName(),
                    List.of(),
                    "");
        }
        if (changes.size() != 1) {
            throw new IllegalStateException(
                    "single-file pass attempted " + changes.size() + " source changes");
        }

        Result result = changes.getFirst();
        SourceFile before = result.getBefore();
        SourceFile after = result.getAfter();
        Path expectedPath = Path.of(normalizedPath);
        if (before == null || after == null) {
            throw new IllegalStateException("single-file pass may not create or delete sources");
        }
        if (!before.getSourcePath().equals(expectedPath)
                || !after.getSourcePath().equals(expectedPath)) {
            throw new IllegalStateException("single-file pass may not move or rename the source");
        }
        if (sourceKind.structured() && after instanceof PlainText) {
            throw new IllegalStateException(
                    "structured source recipe may not downgrade " + sourceKind + " to plain text");
        }

        String output = after.printAll();
        requireTextSource(output);
        parseLosslessly(normalizedPath, output, classpath, sourceKind);
        List<String> descriptors =
                result.getRecipeDescriptorsThatMadeChanges().stream()
                        .map(descriptor -> descriptor.getName())
                        .toList();
        return new M3OpenRewriteExecution(
                normalizedPath,
                source,
                output,
                recipe.getClass().getName(),
                recipe.getDisplayName(),
                descriptors,
                result.diff());
    }

    static String normalizeSourcePath(String sourcePath) {
        return SourcePaths.normalizeSourcePath(sourcePath);
    }

    static String normalizeSourcePathOrDirectory(String sourcePath) {
        return SourcePaths.normalizeSourcePathOrDirectory(sourcePath);
    }


    private static Map<String, String> projectSources(
            Map<String, String> sources) {
        Map<String, String> checked =
                Objects.requireNonNull(sources, "sources");
        if (checked.isEmpty()) {
            throw new IllegalArgumentException("EMPTY_PROJECT");
        }
        TreeMap<String, String> sorted = new TreeMap<>();
        Set<String> portableNames = new HashSet<>();
        for (Map.Entry<String, String> entry : checked.entrySet()) {
            String path = normalizeSourcePathOrDirectory(entry.getKey());
            String text = Objects.requireNonNull(entry.getValue(), "source");
            requireTextSource(text);
            if (!portableNames.add(path.toLowerCase(Locale.ROOT))
                    || sorted.putIfAbsent(path, text) != null) {
                throw new IllegalArgumentException(
                        "DUPLICATE_PROJECT_SOURCE:" + path);
            }
        }
        return Collections.unmodifiableMap(new LinkedHashMap<>(sorted));
    }

    private static List<SourceFile> parseProjectLosslessly(
            Map<String, String> sources,
            List<Path> classpath,
            InMemoryExecutionContext context) {
        TreeMap<M3SourceKind, List<Parser.Input>> grouped = new TreeMap<>();
        sources.entrySet().stream()
                .sorted(Map.Entry.comparingByKey())
                .forEach(
                        entry -> {
                            Path path = Path.of(entry.getKey());
                            M3SourceKind kind = M3SourceKind.classify(path);
                            grouped.computeIfAbsent(kind, ignored -> new ArrayList<>())
                                    .add(
                                            Parser.Input.fromString(
                                                    path,
                                                    entry.getValue(),
                                                    StandardCharsets.UTF_8));
                        });

        ArrayList<SourceFile> parsed = new ArrayList<>(sources.size());
        for (Map.Entry<M3SourceKind, List<Parser.Input>> group :
                grouped.entrySet()) {
            Parser parser =
                    M3OpenRewriteParserRegistry.parserFor(
                            group.getKey(),
                            classpath);
            List<SourceFile> files =
                    parser.parseInputs(group.getValue(), null, context).toList();
            if (files.size() != group.getValue().size()) {
                throw new IllegalArgumentException(
                        "project parser source-count drift for "
                                + group.getKey());
            }
            for (SourceFile source : files) {
                if (source instanceof ParseError error) {
                    throw new IllegalArgumentException(
                            "OpenRewrite could not parse project source "
                                    + source.getSourcePath(), error.toException());
                }
                String path =
                        normalizeSourcePathOrDirectory(
                                source.getSourcePath().toString());
                String expected = sources.get(path);
                if (expected == null || !source.printAll().equals(expected)) {
                    throw new IllegalArgumentException(
                            "project parse/print drift for "
                                    + group.getKey()
                                    + " source "
                                    + path);
                }
                if (group.getKey().structured() && source instanceof PlainText) {
                    throw new IllegalStateException(
                            "structured project source parsed as plain text: "
                                    + path);
                }
                parsed.add(source);
            }
        }
        parsed.sort(
                Comparator.comparing(
                        source ->
                                normalizeSourcePathOrDirectory(
                                        source.getSourcePath().toString())));
        return List.copyOf(parsed);
    }

    private static String resultPath(Result result) {
        SourceFile source =
                result.getBefore() != null
                        ? result.getBefore()
                        : result.getAfter();
        return source == null
                ? ""
                : normalizeSourcePathOrDirectory(
                        source.getSourcePath().toString());
    }

    private static Parsed parseLosslessly(
            String sourcePath,
            String source,
            List<Path> classpath,
            M3SourceKind sourceKind) {
        Path path = Path.of(sourcePath);
        ExecutionContext context = new InMemoryExecutionContext(throwable -> {
            throw new IllegalStateException(
                    "OpenRewrite execution failed for " + sourcePath,
                    throwable);
        });
        Parser parser = M3OpenRewriteParserRegistry.parserFor(sourceKind, classpath);
        List<SourceFile> parsed =
                parser.parseInputs(
                                List.of(Parser.Input.fromString(path, source)),
                                null,
                                context)
                        .toList();
        if (parsed.size() != 1) {
            throw new IllegalStateException(
                    "expected exactly one parsed source: " + sourcePath);
        }
        SourceFile parsedSource = parsed.getFirst();
        if (parsedSource instanceof ParseError) {
            throw new IllegalArgumentException(
                    "OpenRewrite could not parse " + sourceKind + " source " + sourcePath);
        }
        if (!parsedSource.getSourcePath().equals(path)) {
            throw new IllegalStateException("parser changed source path");
        }
        if (!parsedSource.printAll().equals(source)) {
            throw new IllegalArgumentException(
                    "OpenRewrite parse/print was not lossless for "
                            + sourceKind + " source " + sourcePath);
        }
        return new Parsed(parsedSource, context);
    }

    private static List<Path> classpath(List<Path> classpath) {
        List<Path> checked = List.copyOf(Objects.requireNonNull(classpath, "classpath"));
        checked.forEach(path -> Objects.requireNonNull(path, "classpath entry"));
        return checked;
    }

    private static void requireUniquePassIds(List<M3TranspilePass> passes) {
        Set<String> ids = new HashSet<>();
        for (M3TranspilePass pass : passes) {
            Objects.requireNonNull(pass, "pass");
            if (!ids.add(pass.id())) {
                throw new IllegalArgumentException("duplicate pass id: " + pass.id());
            }
        }
    }

    private static void requireTextSource(String source) {
        Objects.requireNonNull(source, "source");
        if (source.indexOf('\0') >= 0) {
            throw new IllegalArgumentException("binary/NUL-bearing source is outside OpenRewrite text mutation authority");
        }
    }

    private static String sha256(String value) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of()
                    .formatHex(digest.digest(value.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException("SHA-256 unavailable", impossible);
        }
    }

    private record Parsed(SourceFile source, ExecutionContext context) {}
}

