    private static final String CRATE = "sealed-readonly-requirement";
    private static final String RESOURCE = "/com/synexia/rewrite/hash-pinned-java/" + CRATE + "/";
    private static final String HIERARCHY =
            "src/main/java/com/synexia/rewrite/sealed/SealedHierarchyReview.java";
    private static final String ENGINE =
            "src/main/java/com/synexia/rewrite/sealed/SealedRecipeEngine.java";
    private static final String TEST =
            "src/test/java/com/synexia/rewrite/sealed/SealedReadOnlyRequirementTest.java";

    @Test
    void exposesExactTargetPreimagesAndNarrowestRequiredScope() {
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);

        assertEquals(List.of(ENGINE, HIERARCHY, TEST).stream().sorted().toList(),
                recipe.targetPaths());
        assertEquals(3, recipe.preimageManifest().size());
        assertTrue(recipe.preimageManifest().get(TEST).equals("ABSENT"));
        assertTrue(recipe.preimageManifest().get(ENGINE).matches("[0-9a-f]{64}"));
        assertTrue(recipe.preimageManifest().get(HIERARCHY).matches("[0-9a-f]{64}"));
        assertEquals(M3EditScope.PACKAGE, recipe.requiredScope());

        M3RecipeFirstInvariant.requireHashPinnedRecipeScope(recipe, M3EditScope.PACKAGE);
        assertThrows(
                IllegalStateException.class,
                () -> M3RecipeFirstInvariant.requireHashPinnedRecipeScope(
                        recipe, M3EditScope.FILE));
    }

    @Test
    void appliesReviewedSnapshotThenReplaysWithoutChanges() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        List<SourceFile> before = parse(context, Map.of(
                HIERARCHY, resource("pre/SealedHierarchyReview.java.txt"),
                ENGINE, resource("pre/SealedRecipeEngine.java.txt")));
        var applied = recipe.run(new InMemoryLargeSourceSet(before), context, 1);
        Map<String, String> expected = afterTexts();
        Map<String, String> actual = new TreeMap<>();
        for (var result : applied.getChangeset().getAllResults()) {
            assertNotNull(result.getAfter());
            actual.put(normalized(result.getAfter().getSourcePath()),
                    result.getAfter().printAll());
        }
        assertEquals(expected, actual);
        assertEquals(1, recipe.maxCycles());

        List<SourceFile> after = parse(context, expected);
        var replayed = recipe.run(new InMemoryLargeSourceSet(after), context, 1);
        assertTrue(replayed.getChangeset().getAllResults().isEmpty());
    }

    @Test
    void refusesSourceDriftBeforeProducingAnyCandidate() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        var inventory = recipe.getInitialValue(context);
        List<SourceFile> drifted = parse(context, Map.of(
                HIERARCHY, resource("pre/SealedHierarchyReview.java.txt"),
                ENGINE, resource("pre/SealedRecipeEngine.java.txt") + "// drift\n"));
        var scanner = recipe.getScanner(inventory);
        for (SourceFile file : drifted) scanner.visit(file, context);
        IllegalStateException failure = assertThrows(IllegalStateException.class,
                () -> recipe.generate(inventory, context));
        assertTrue(failure.getMessage().contains("source drift"));
    }

    @Test
    void refusesMissingRequiredPreimageAndInvalidCrateName() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        var inventory = recipe.getInitialValue(context);
        recipe.getScanner(inventory).visit(
                parse(context, Map.of(ENGINE,
                        resource("pre/SealedRecipeEngine.java.txt"))).get(0), context);
        IllegalStateException failure = assertThrows(IllegalStateException.class,
                () -> recipe.generate(inventory, context));
        assertTrue(failure.getMessage().contains("required source missing"));
        assertThrows(IllegalArgumentException.class,
                () -> new M3HashPinnedJavaSnapshotRecipe("../escape"));
    }

    @Test
    void rejectsMatchingTextThatWasNotParsedAsJava() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        var inventory = recipe.getInitialValue(context);
        SourceFile plainText = PlainText.builder().sourcePath(Path.of(ENGINE))
                .text(resource("pre/SealedRecipeEngine.java.txt")).build();
        recipe.getScanner(inventory).visit(plainText, context);
        recipe.getScanner(inventory).visit(parse(context, Map.of(HIERARCHY,
                resource("pre/SealedHierarchyReview.java.txt"))).get(0), context);
        IllegalStateException failure = assertThrows(IllegalStateException.class,
                () -> recipe.generate(inventory, context));
        assertTrue(failure.getMessage().contains("not a Java compilation unit"));
    }

    @Test
    void preparesAllOutputsBeforeEmittingAnyCandidate() {
        var context = new InMemoryExecutionContext(error -> { });
        var recipe = new M3HashPinnedJavaSnapshotRecipe("malformed-candidate");
        var inventory = recipe.getInitialValue(context);
        IllegalStateException failure = assertThrows(IllegalStateException.class,
                () -> recipe.generate(inventory, context));
        assertTrue(failure.getMessage().contains("Java template parse/format drift"));
        RuntimeException visitFailure = assertThrows(RuntimeException.class,
                () -> recipe.getVisitor(inventory).visit(
                        parse(context, Map.of(ENGINE,
                                resource("pre/SealedRecipeEngine.java.txt"))).get(0), context));
        assertTrue(visitFailure.getCause() instanceof IllegalStateException);
        assertTrue(visitFailure.getCause().getMessage()
                .contains("Java template parse/format drift"));
    }

    @Test
    void rejectsInterleavedEditAfterSuccessfulScan() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        var inventory = recipe.getInitialValue(context);
        for (SourceFile file : parse(context, Map.of(
                HIERARCHY, resource("pre/SealedHierarchyReview.java.txt"),
                ENGINE, resource("pre/SealedRecipeEngine.java.txt")))) {
            recipe.getScanner(inventory).visit(file, context);
        }
        recipe.generate(inventory, context);
        SourceFile edited = parse(context, Map.of(ENGINE,
                resource("pre/SealedRecipeEngine.java.txt") + "// interleaved edit\n")).get(0);
        RuntimeException drift = assertThrows(RuntimeException.class,
                () -> recipe.getVisitor(inventory).visit(edited, context));
        assertTrue(drift.getCause() instanceof IllegalStateException);
        assertTrue(drift.getCause().getMessage().contains("target changed after scan"));

        SourceFile nonJava = PlainText.builder().sourcePath(Path.of(ENGINE))
                .text(resource("pre/SealedRecipeEngine.java.txt")).build();
        RuntimeException typeDrift = assertThrows(RuntimeException.class,
                () -> recipe.getVisitor(inventory).visit(nonJava, context));
        assertTrue(typeDrift.getCause() instanceof IllegalStateException);
        assertTrue(typeDrift.getCause().getMessage().contains("target changed after scan"));

        var alreadyMigrated = recipe.getInitialValue(context);
        for (SourceFile file : parse(context, Map.of(
                HIERARCHY, resource("pre/SealedHierarchyReview.java.txt"),
                ENGINE, resource("SealedRecipeEngine.java.txt")))) {
            recipe.getScanner(alreadyMigrated).visit(file, context);
        }
        recipe.generate(alreadyMigrated, context);
        SourceFile reverted = parse(context, Map.of(ENGINE,
                resource("pre/SealedRecipeEngine.java.txt"))).get(0);
        RuntimeException changedToAnotherManifestHash = assertThrows(RuntimeException.class,
                () -> recipe.getVisitor(alreadyMigrated).visit(reverted, context));
        assertTrue(changedToAnotherManifestHash.getCause() instanceof IllegalStateException);
        assertTrue(changedToAnotherManifestHash.getCause().getMessage()
                .contains("target changed after scan"));
    }

    @Test
    void keepsEncodingAndBomWhileClearingObsoleteChecksum() {
        var context = context();
        var recipe = new M3HashPinnedJavaSnapshotRecipe(CRATE);
        List<SourceFile> originals = parse(context, Map.of(
                HIERARCHY, resource("pre/SealedHierarchyReview.java.txt"),
                ENGINE, resource("pre/SealedRecipeEngine.java.txt")));
        SourceFile engine = originals.stream().filter(source ->
                normalized(source.getSourcePath()).equals(ENGINE)).findFirst().orElseThrow();
        var originalMetadata = new BuildMetadata(
                UUID.fromString("bba80867-4d0f-4faa-b202-1990c36d5025"),
                Map.of("fixture", "snapshot metadata witness"));
        SourceFile marked = engine.<SourceFile>withMarkers(engine.getMarkers().add(originalMetadata))
                .withCharset(StandardCharsets.UTF_16)
                .withCharsetBomMarked(true)
                .withChecksum(Checksum.fromHex("SHA-256", "00"));
        List<SourceFile> before = originals.stream()
                .map(source -> source == engine ? marked : source).toList();
        var run = recipe.run(new InMemoryLargeSourceSet(before), context, 1);
        SourceFile after = run.getChangeset().getAllResults().stream()
                .map(result -> result.getAfter())
                .filter(source -> source != null && normalized(source.getSourcePath()).equals(ENGINE))
                .findFirst().orElseThrow();
        assertEquals(marked.getId(), after.getId());
        assertEquals(marked.getSourcePath(), after.getSourcePath());
        assertEquals(marked.getMarkers(),
                after.getMarkers().removeByType(RecipesThatMadeChanges.class));
        var retainedMetadata = after.getMarkers().findFirst(BuildMetadata.class).orElseThrow();
        assertSame(originalMetadata, retainedMetadata);
        assertEquals(originalMetadata.getId(), retainedMetadata.getId());
        assertEquals(originalMetadata.getMetadata(), retainedMetadata.getMetadata());
        var provenance = after.getMarkers().findAll(RecipesThatMadeChanges.class);
        assertEquals(1, provenance.size());
        var recipeStacks = List.copyOf(provenance.get(0).getRecipes());
        assertEquals(List.of(List.of(recipe)), recipeStacks);
        assertSame(recipe, recipeStacks.get(0).get(0));
        assertEquals(CRATE,
                ((M3HashPinnedJavaSnapshotRecipe) recipeStacks.get(0).get(0)).getCrateName());
        assertEquals(marked.getFileAttributes(), after.getFileAttributes());
        assertEquals(StandardCharsets.UTF_16, after.getCharset());
        assertTrue(after.isCharsetBomMarked());
        assertEquals(null, after.getChecksum());
    }

    @Test
    void admitsAlternateJavaSourceSetsUnderSrcJavaRoots() {
