    @Test
    void namedMavenRecipeCrateIsRegisteredForDryRun() throws IOException {
        String yaml = resourceFrom(
                "/META-INF/rewrite/m3-sealed-readonly-requirement.yml");
        assertTrue(yaml.contains("name: com.synexia.rewrite.M3SealedReadOnlyRequirementMigration"));
        assertTrue(yaml.contains("M3HashPinnedJavaSnapshotRecipe"));
        assertTrue(yaml.contains("crateName: " + CRATE));
        Path pomPath = Path.of("synexia-openrewrite-recipes/pom.xml");
        if (!Files.isRegularFile(pomPath)) pomPath = Path.of("pom.xml");
        String pom = Files.readString(pomPath);
        assertTrue(pom.contains("<id>m3-sealed-readonly-requirement-migration</id>"));
        assertTrue(pom.contains(
                "<recipe>com.synexia.rewrite.M3SealedReadOnlyRequirementMigration</recipe>"));

        var activated = Environment.builder().scanRuntimeClasspath("com.synexia.rewrite")
                .build().activateRecipes(
                        "com.synexia.rewrite.M3SealedReadOnlyRequirementMigration");
        var declared = activated.getRecipeList().get(0);
        assertEquals("com.synexia.rewrite.M3SealedReadOnlyRequirementMigration",
                declared.getName());
        var configured = declared.getRecipeList().get(0);
        assertTrue(configured instanceof M3HashPinnedJavaSnapshotRecipe);
        assertEquals(CRATE, ((M3HashPinnedJavaSnapshotRecipe) configured).getCrateName());
    }

    private static Map<String, String> afterTexts() {
        return Map.of(
                HIERARCHY, resource("SealedHierarchyReview.java.txt"),
                ENGINE, resource("SealedRecipeEngine.java.txt"),
                TEST, resource("SealedReadOnlyRequirementTest.java.txt"));
    }

    private static List<SourceFile> parse(InMemoryExecutionContext context,
            Map<String, String> input) {
        List<Parser.Input> entries = new TreeMap<>(input).entrySet().stream()
                .map(entry -> Parser.Input.fromString(
                        Path.of(entry.getKey()), entry.getValue())).toList();
        return JavaParser.fromJavaVersion().build()
                .parseInputs(entries, null, context).toList();
    }

    private static InMemoryExecutionContext context() {
        return new InMemoryExecutionContext(error -> {
            throw new AssertionError(error);
        });
    }

    private static String resource(String name) {
        return resourceFrom(RESOURCE + name);
    }

    private static String resourceFrom(String name) {
        try (var stream = M3HashPinnedJavaSnapshotRecipeTest.class.getResourceAsStream(name)) {
            assertNotNull(stream, name);
            return new String(stream.readAllBytes(), StandardCharsets.UTF_8);
        } catch (IOException failure) {
            throw new IllegalStateException(failure);
        }
    }

    private static String normalized(Path path) {
        return path.toString().replace('\\', '/');
    }
